    let geoBlazorId = lookupGeoBlazorId(jsObject);
    if (hasValue(geoBlazorId)) {
        dotNetCatalogFootprintLayer.id = geoBlazorId;
    } else if (hasValue(viewId)) {
        let dotNetRef = dotNetRefs[viewId!];
        if (hasValue(dotNetRef)) {
            try {
                dotNetCatalogFootprintLayer.id = await dotNetRef.invokeMethodAsync('GetId');
            } catch (e) {
                console.error('Error invoking GetId for CatalogFootprintLayer', e);
            }
        }
    }

    if (hasValue(dotNetCatalogFootprintLayer.id)) {
        if (!jsObjectRefs.hasOwnProperty(dotNetCatalogFootprintLayer.id)) {
            let { default: CatalogFootprintLayerWrapper } = await import('./catalogFootprintLayer');
            let catalogFootprintLayerWrapper = new CatalogFootprintLayerWrapper(jsObject);
            catalogFootprintLayerWrapper.geoBlazorId = dotNetCatalogFootprintLayer.id;
            catalogFootprintLayerWrapper.viewId = viewId;
            catalogFootprintLayerWrapper.layerId = layerId;
            jsObjectRefs[dotNetCatalogFootprintLayer.id] = catalogFootprintLayerWrapper;
        }
        arcGisObjectRefs[dotNetCatalogFootprintLayer.id] ??= jsObject;
    }
    return dotNetCatalogFootprintLayer;
